const std = @import("std");

pub fn main() !void {
    const values = [_]u32{ 1000, 900, 500, 400, 100, 90, 50, 40, 10, 9, 5, 4, 1 };
    const numerals = [_][]const u8{ "M", "CM", "D", "CD", "C", "XC", "L", "XL", "X", "IX", "V", "IV", "I" };
    var num: u32 = 1984;

    for (values, numerals) |val, sym| {
        while (num >= val) {
            std.debug.print("{s}", .{sym});
            num -= val;
        }
    }
    std.debug.print("\n", .{});
}

